// Generates packages/schema/types.ts from the JSON Schemas. Run: npm run gen:types
import { writeFileSync } from 'node:fs';
import { join, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { compileFromFile } from 'json-schema-to-typescript';

const dir = dirname(fileURLToPath(import.meta.url));
const opts = { bannerComment: '', additionalProperties: false, cwd: dir, style: { singleQuote: true }, ignoreMinAndMaxItems: true };
const out = [
  '// Generated by gen.mjs from bank.schema.json and event.schema.json. Do not edit.',
  await compileFromFile(join(dir, 'bank.schema.json'), opts),
  await compileFromFile(join(dir, 'event.schema.json'), opts),
].join('\n');
writeFileSync(join(dir, 'types.ts'), out);
console.log('wrote types.ts');
